/* ── SCM_ADM_MNU_BTN_MPG_M — 버튼 → API 매핑 · upsert · 키 MNU_ID, SHT_NM, MNU_BTN_CD (PK) · 20행 */
MERGE INTO SCM_MGR.SCM_ADM_MNU_BTN_MPG_M T
USING (SELECT 'DMF0008' MNU_ID, 'division' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_DMF0008_DIVISION_GET' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'main' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_DMF0008_SUMMARY_GET' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'main' SHT_NM, 'STATUS_UPDATE' MNU_BTN_CD, 'P_DMF0008_STATUS_UPDATE' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'project' SHT_NM, 'DELETE' MNU_BTN_CD, NULL API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'project' SHT_NM, 'SAVE' MNU_BTN_CD, 'P_DMF0008_PROJECT_SAVE' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'project' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_DMF0008_PROJECT_GET' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'repair' SHT_NM, 'DELETE' MNU_BTN_CD, NULL API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'repair' SHT_NM, 'SAVE' MNU_BTN_CD, 'P_DMF0008_REPAIR_SAVE' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'repair' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_DMF0008_REPAIR_GET' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'salesSite' SHT_NM, 'DELETE' MNU_BTN_CD, NULL API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'salesSite' SHT_NM, 'INSERT' MNU_BTN_CD, NULL API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'salesSite' SHT_NM, 'SAVE' MNU_BTN_CD, 'P_DMF0008_SALES_SITE_SAVE' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'salesSite' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_DMF0008_SALES_SITE_GET' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'site' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_DMF0008_SITE_GET' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'sspm' SHT_NM, 'DELETE' MNU_BTN_CD, NULL API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'sspm' SHT_NM, 'INSERT' MNU_BTN_CD, NULL API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'sspm' SHT_NM, 'SAVE' MNU_BTN_CD, 'P_DMF0008_SSPM_SAVE' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'sspm' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_DMF0008_SSPM_GET' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'summary' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_DMF0008_SUMMARY_GET' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'DMF0008' MNU_ID, 'updateHistory' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_DMF0008_UPDATE_HISTORY_GET' API_ID, 'Y' USE_YN FROM DUAL) S
   ON (NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~') AND NVL(TO_CHAR(T.SHT_NM), '~') = NVL(TO_CHAR(S.SHT_NM), '~') AND NVL(TO_CHAR(T.MNU_BTN_CD), '~') = NVL(TO_CHAR(S.MNU_BTN_CD), '~'))
 WHEN MATCHED THEN UPDATE SET T.API_ID = S.API_ID, T.USE_YN = S.USE_YN, T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = SYSDATE
      WHERE DECODE(T.API_ID, S.API_ID, 0, 1) = 1 OR DECODE(T.USE_YN, S.USE_YN, 0, 1) = 1
 WHEN NOT MATCHED THEN INSERT (MNU_ID, SHT_NM, MNU_BTN_CD, API_ID, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
      VALUES (S.MNU_ID, S.SHT_NM, S.MNU_BTN_CD, S.API_ID, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE);

