 WHEN MATCHED THEN UPDATE SET T.COLUMN_LABEL_NAME = S.COLUMN_LABEL_NAME, T.SORT_ORDER_NO = S.SORT_ORDER_NO, T.DATA_SORT_METHOD_CODE = S.DATA_SORT_METHOD_CODE, T.SMALL_CLASS_LABEL_NAME = S.SMALL_CLASS_LABEL_NAME, T.LARGE_CLASS_LABEL_NAME = S.LARGE_CLASS_LABEL_NAME, T.FIXED_FLAG = S.FIXED_FLAG, T.COLUMN_WIDTH = S.COLUMN_WIDTH, T.CELL_CONTROL_OBJECT_TYPE_CODE = S.CELL_CONTROL_OBJECT_TYPE_CODE, T.CELL_COMBO_DATA_TYPE = S.CELL_COMBO_DATA_TYPE, T.DATA_SCALE_NUMBER = S.DATA_SCALE_NUMBER, T.DATA_MAX_LENGTH = S.DATA_MAX_LENGTH, T.HORIZONTAL_ALIGN_CODE = S.HORIZONTAL_ALIGN_CODE, T.UPPERCASE_APPLY_FLAG = S.UPPERCASE_APPLY_FLAG, T.VISIBLE_FLAG = S.VISIBLE_FLAG, T.DIVISION_ID = S.DIVISION_ID, T.DEFAULT_FLAG = S.DEFAULT_FLAG, T.USER_SELECTABLE_FLAG = S.USER_SELECTABLE_FLAG, T.VALID_YN = S.VALID_YN, T.ATTRIBUTE1 = S.ATTRIBUTE1, T.ATTRIBUTE2 = S.ATTRIBUTE2, T.ATTRIBUTE3 = S.ATTRIBUTE3, T.ATTRIBUTE4 = S.ATTRIBUTE4, T.ATTRIBUTE5 = S.ATTRIBUTE5, T.ATTRIBUTE6 = S.ATTRIBUTE6, T.ATTRIBUTE7 = S.ATTRIBUTE7, T.ATTRIBUTE8 = S.ATTRIBUTE8, T.ATTRIBUTE9 = S.ATTRIBUTE9, T.ATTRIBUTE10 = S.ATTRIBUTE10, T.INPUT_TP_CD = S.INPUT_TP_CD, T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = SYSDATE
      WHERE DECODE(T.COLUMN_LABEL_NAME, S.COLUMN_LABEL_NAME, 0, 1) = 1 OR DECODE(T.SORT_ORDER_NO, S.SORT_ORDER_NO, 0, 1) = 1 OR DECODE(T.DATA_SORT_METHOD_CODE, S.DATA_SORT_METHOD_CODE, 0, 1) = 1 OR DECODE(T.SMALL_CLASS_LABEL_NAME, S.SMALL_CLASS_LABEL_NAME, 0, 1) = 1 OR DECODE(T.LARGE_CLASS_LABEL_NAME, S.LARGE_CLASS_LABEL_NAME, 0, 1) = 1 OR DECODE(T.FIXED_FLAG, S.FIXED_FLAG, 0, 1) = 1 OR DECODE(T.COLUMN_WIDTH, S.COLUMN_WIDTH, 0, 1) = 1 OR DECODE(T.CELL_CONTROL_OBJECT_TYPE_CODE, S.CELL_CONTROL_OBJECT_TYPE_CODE, 0, 1) = 1 OR DECODE(T.CELL_COMBO_DATA_TYPE, S.CELL_COMBO_DATA_TYPE, 0, 1) = 1 OR DECODE(T.DATA_SCALE_NUMBER, S.DATA_SCALE_NUMBER, 0, 1) = 1 OR DECODE(T.DATA_MAX_LENGTH, S.DATA_MAX_LENGTH, 0, 1) = 1 OR DECODE(T.HORIZONTAL_ALIGN_CODE, S.HORIZONTAL_ALIGN_CODE, 0, 1) = 1 OR DECODE(T.UPPERCASE_APPLY_FLAG, S.UPPERCASE_APPLY_FLAG, 0, 1) = 1 OR DECODE(T.VISIBLE_FLAG, S.VISIBLE_FLAG, 0, 1) = 1 OR DECODE(T.DIVISION_ID, S.DIVISION_ID, 0, 1) = 1 OR DECODE(T.DEFAULT_FLAG, S.DEFAULT_FLAG, 0, 1) = 1 OR DECODE(T.USER_SELECTABLE_FLAG, S.USER_SELECTABLE_FLAG, 0, 1) = 1 OR DECODE(T.VALID_YN, S.VALID_YN, 0, 1) = 1 OR DECODE(T.ATTRIBUTE1, S.ATTRIBUTE1, 0, 1) = 1 OR DECODE(T.ATTRIBUTE2, S.ATTRIBUTE2, 0, 1) = 1 OR DECODE(T.ATTRIBUTE3, S.ATTRIBUTE3, 0, 1) = 1 OR DECODE(T.ATTRIBUTE4, S.ATTRIBUTE4, 0, 1) = 1 OR DECODE(T.ATTRIBUTE5, S.ATTRIBUTE5, 0, 1) = 1 OR DECODE(T.ATTRIBUTE6, S.ATTRIBUTE6, 0, 1) = 1 OR DECODE(T.ATTRIBUTE7, S.ATTRIBUTE7, 0, 1) = 1 OR DECODE(T.ATTRIBUTE8, S.ATTRIBUTE8, 0, 1) = 1 OR DECODE(T.ATTRIBUTE9, S.ATTRIBUTE9, 0, 1) = 1 OR DECODE(T.ATTRIBUTE10, S.ATTRIBUTE10, 0, 1) = 1 OR DECODE(T.INPUT_TP_CD, S.INPUT_TP_CD, 0, 1) = 1
 WHEN NOT MATCHED THEN INSERT (PROGRAM_ID, SHEET_NAME, COLUMN_NAME, COLUMN_LABEL_NAME, SORT_ORDER_NO, DATA_SORT_METHOD_CODE, SMALL_CLASS_LABEL_NAME, LARGE_CLASS_LABEL_NAME, FIXED_FLAG, COLUMN_WIDTH, CELL_CONTROL_OBJECT_TYPE_CODE, CELL_COMBO_DATA_TYPE, DATA_SCALE_NUMBER, DATA_MAX_LENGTH, HORIZONTAL_ALIGN_CODE, UPPERCASE_APPLY_FLAG, VISIBLE_FLAG, DIVISION_ID, DEFAULT_FLAG, USER_SELECTABLE_FLAG, VALID_YN, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, INPUT_TP_CD, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
      VALUES (S.PROGRAM_ID, S.SHEET_NAME, S.COLUMN_NAME, S.COLUMN_LABEL_NAME, S.SORT_ORDER_NO, S.DATA_SORT_METHOD_CODE, S.SMALL_CLASS_LABEL_NAME, S.LARGE_CLASS_LABEL_NAME, S.FIXED_FLAG, S.COLUMN_WIDTH, S.CELL_CONTROL_OBJECT_TYPE_CODE, S.CELL_COMBO_DATA_TYPE, S.DATA_SCALE_NUMBER, S.DATA_MAX_LENGTH, S.HORIZONTAL_ALIGN_CODE, S.UPPERCASE_APPLY_FLAG, S.VISIBLE_FLAG, S.DIVISION_ID, S.DEFAULT_FLAG, S.USER_SELECTABLE_FLAG, S.VALID_YN, S.ATTRIBUTE1, S.ATTRIBUTE2, S.ATTRIBUTE3, S.ATTRIBUTE4, S.ATTRIBUTE5, S.ATTRIBUTE6, S.ATTRIBUTE7, S.ATTRIBUTE8, S.ATTRIBUTE9, S.ATTRIBUTE10, S.INPUT_TP_CD, 'admin', SYSDATE, 'admin', SYSDATE);

