SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'SYSTEM' SQL_ID, 'ALL' MDU_DIVS_CD, 'Lookup System' SQL_NM, '    SELECT  T1.SEGMENT1 CODE, T1.SEGMENT2 NAME' || CHR(13) || CHR(10) || '     FROM  SCM_ADM_LOOKUP_MASTER_DETAIL T1' || CHR(13) || CHR(10) || '    WHERE  1=1' || CHR(13) || CHR(10) || '      AND  T1.LOOKUP_TYPE = ''SYSTEM''' || CHR(13) || CHR(10) || '      AND  T1.VALID_YN = ''Y''' || CHR(13) || CHR(10) || ' ORDER BY  T1.DISPLAY_SEQ' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'SalesCompany' SQL_ID, 'ALL' MDU_DIVS_CD, 'Sales Company 조회' SQL_NM, 'SELECT *' || CHR(10) || '  FROM (' || CHR(10) || '--[E20260812-SALESCOMPANY-V2] AS-IS UP_FX ''SalesCompany'' IF/ELSE 2분기 원문보존 변환 (가드=@itemId 빈값 상호배타. DIVISION_ID 컬럼=TO-BE 확장 유지)' || CHR(10) || 'SELECT DISTINCT' || CHR(10) || '	   S.DIVISION_ID AS DIVISION_ID' || CHR(10) || '	 , S.COMPANY_ID AS CODE' || CHR(10) || '	 , S.COMPANY_ID AS NAME' || CHR(10) || 'FROM   SCM_MST_SITE S' || CHR(10) || 'WHERE  SITE_TYPE = ''PLANT''' || CHR(10) || 'AND    (@plantId IS NULL OR @plantId='''' OR PLANT_ID=@plantId)' || CHR(10) || 'AND    (@divisionId IS NULL OR @divisionId='''' OR S.DIVISION_ID=@divisionId)' || CHR(10) || 'AND    ( @itemId IS NULL OR @itemId = '''' )  -- 원문 IF ( @Param4 = '''' ) 직역' || CHR(10) || 'UNION ALL' || CHR(10) || 'SELECT DISTINCT' || CHR(10) || '	   S.DIVISION_ID AS DIVISION_ID' || CHR(10) || '	 , COMPANY_ID AS CODE' || CHR(10) || '	 , COMPANY_ID AS NAME' || CHR(10) || 'FROM   SCM_MST_SITE S' || CHR(10) || 'WHERE  1 = 1' || CHR(10) || 'AND    SITE_TYPE = ''CORP''' || CHR(10) || 'AND    (@plantId IS NULL OR @plantId='''' OR PLANT_ID=@plantId)' || CHR(10) || 'AND    (@divisionId IS NULL OR @divisionId='''' OR S.DIVISION_ID=@divisionId)' || CHR(10) || 'AND    ( @itemId IS NULL OR @itemId = '''' )' || CHR(10) || '-- ══ ELSE 분기 (@Param4 존재 — ITEM 기반) — 원문 1:1 ══' || CHR(10) || 'UNION ALL' || CHR(10) || 'SELECT DISTINCT' || CHR(10) || '	   S.DIVISION_ID AS DIVISION_ID' || CHR(10) || '	 , S.COMPANY_ID AS CODE' || CHR(10) || '	 , S.COMPANY_ID AS NAME' || CHR(10) || 'FROM   SCM_MST_SITE S' || CHR(10) || 'INNER JOIN (SELECT DISTINCT I.DIVISION_ID, I.COMPANY_ID, I.SCP_OPERATION_GROUP --[C20200608-000328] SalesCompany 콤보는 Item Master의 Company ID, Operation Group 기준으로 조회' || CHR(10) || '			FROM   SCM_MST_PROJECT_ITEM SI' || CHR(10) || '			INNER JOIN SCM_MST_ITEM_SN I' || CHR(10) || '			ON     SI.ITEM_ID = I.ITEM_ID' || CHR(10) || '			WHERE  1=1 --[C20200818-000264] Project_Item Master Valid 조건 제외, Item Master Valid 조건 추가' || CHR(10) || '			AND    I.ACTIVE_FLAG = ''Y''' || CHR(10) || '			AND    (I.DIVISION_ID LIKE ''81%'' OR I.DIVISION_ID = ''82'')' || CHR(10) || '			AND    I.ITEM_TYPE IS NOT NULL --[C20200626-000172]' || CHR(10) || '			AND    (@divisionId IS NULL OR @divisionId='''' OR SI.DIVISION_ID=@divisionId)' || CHR(10) || '			AND    (@projectCode IS NULL OR @projectCode='''' OR SI.PROJECT_CODE=@projectCode)' || CHR(10) || '			AND    (@itemId IS NULL OR @itemId='''' OR SI.ITEM_ID=@itemId)' || CHR(10) || '			UNION ALL' || CHR(10) || '			SELECT DISTINCT I.DIVISION_ID, I.COMPANY_ID, I.SCP_OPERATION_GROUP' || CHR(10) || '			FROM   SCM_MST_ITEM_SN I' || CHR(10) || '			WHERE  1=1' || CHR(10) || '			AND    I.ACTIVE_FLAG = ''Y''' || CHR(10) || '			AND    I.DIVISION_ID IN (''40'')' || CHR(10) || '			AND    I.ITEM_TYPE IS NOT NULL' || CHR(10) || '			AND    (@divisionId IS NULL OR @divisionId='''' OR I.DIVISION_ID=@divisionId)' || CHR(10) || '			AND    (@itemId IS NULL OR @itemId='''' OR I.ITEM_ID=@itemId)' || CHR(10) || '			) SS' || CHR(10) || 'ON  S.DIVISION_ID = SS.DIVISION_ID' || CHR(10) || 'AND S.OPERATION_GROUP = NVL(SS.SCP_OPERATION_GROUP, S.OPERATION_GROUP)' || CHR(10) || 'AND S.COMPANY_ID = SS.COMPANY_ID' || CHR(10) || 'WHERE  1 = 1' || CHR(10) || 'AND    SITE_TYPE = ''PLANT''' || CHR(10) || '--AND    OSP_YN    <> ''Y''' || CHR(10) || 'AND    (@plantId IS NULL OR @plantId='''' OR PLANT_ID=@plantId)' || CHR(10) || 'AND    (@divisionId IS NULL OR @divisionId='''' OR S.DIVISION_ID=@divisionId)' || CHR(10) || 'AND    @itemId IS NOT NULL  -- 원문 ELSE — ''''=NULL 방언(<>'''' 직역은 항상 UNKNOWN)' || CHR(10) || 'UNION ALL' || CHR(10) || 'SELECT DISTINCT' || CHR(10) || '	   S.DIVISION_ID AS DIVISION_ID' || CHR(10) || '	 , COMPANY_ID AS CODE' || CHR(10) || '	 , COMPANY_ID AS NAME' || CHR(10) || 'FROM   SCM_MST_SITE S' || CHR(10) || 'WHERE  1 = 1' || CHR(10) || 'AND    SITE_TYPE = ''CORP''' || CHR(10) || 'AND    (@plantId IS NULL OR @plantId='''' OR PLANT_ID=@plantId)' || CHR(10) || 'AND    (@divisionId IS NULL OR @divisionId='''' OR S.DIVISION_ID=@divisionId)' || CHR(10) || 'AND    @itemId IS NOT NULL' || CHR(10) || '       )' || CHR(10) || ' ORDER BY UPPER(CODE)' || CHR(10) || '        , UPPER(NAME)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'SalesPlant' SQL_ID, 'ALL' MDU_DIVS_CD, 'Sales Plant 조회' SQL_NM, 'SELECT *' || CHR(10) || '  FROM (' || CHR(10) || '--[E20260812-SALESPLANT-V2] AS-IS UP_FX ''SalesPlant'' IF/ELSE 2분기 원문보존 변환 (가드=@itemId 빈값 상호배타. 상세: Doc/화면분석서)' || CHR(10) || 'SELECT DISTINCT' || CHR(10) || '	   S.DIVISION_ID AS DIVISION_ID' || CHR(10) || '	 , CASE WHEN OSP_YN = ''Y'' THEN LOGISTIC_PLANT_ID ELSE PLANT_ID END AS CODE' || CHR(10) || '	 , CASE WHEN OSP_YN = ''Y'' THEN LOGISTIC_PLANT_ID ELSE PLANT_ID END AS NAME' || CHR(10) || 'FROM   SCM_MST_SITE S' || CHR(10) || 'WHERE  1 = 1' || CHR(10) || 'AND    SITE_TYPE = ''PLANT''' || CHR(10) || '--AND    OSP_YN    <> ''Y''' || CHR(10) || 'AND    (@companyId IS NULL OR @companyId='''' OR S.COMPANY_ID=@companyId)' || CHR(10) || 'AND    (@divisionId IS NULL OR @divisionId='''' OR S.DIVISION_ID=@divisionId)' || CHR(10) || 'AND    ( @itemId IS NULL OR @itemId = '''' )  -- 원문 IF ISNULL(@Param4,'''')='''' 직역' || CHR(10) || 'UNION ALL' || CHR(10) || 'SELECT DISTINCT' || CHR(10) || '	   S.DIVISION_ID AS DIVISION_ID' || CHR(10) || '	 , PLANT_ID AS CODE' || CHR(10) || '	 , PLANT_ID AS NAME' || CHR(10) || 'FROM   SCM_MST_SITE S' || CHR(10) || 'WHERE  1 = 1' || CHR(10) || 'AND    SITE_TYPE = ''CORP''' || CHR(10) || 'AND    (@companyId IS NULL OR @companyId='''' OR S.COMPANY_ID=@companyId)' || CHR(10) || 'AND    (@divisionId IS NULL OR @divisionId='''' OR S.DIVISION_ID=@divisionId)' || CHR(10) || 'AND    ( @itemId IS NULL OR @itemId = '''' )  -- 원문 IF ISNULL(@Param4,'''')='''' 직역' || CHR(10) || '-- ══ ELSE 분기 (@Param4 존재 — ITEM 기반) — 원문 1:1 ══' || CHR(10) || 'UNION ALL' || CHR(10) || 'SELECT DISTINCT' || CHR(10) || '	   S.DIVISION_ID AS DIVISION_ID' || CHR(10) || '	 , CASE WHEN OSP_YN = ''Y'' THEN LOGISTIC_PLANT_ID ELSE PLANT_ID END AS CODE' || CHR(10) || '	 , CASE WHEN OSP_YN = ''Y'' THEN LOGISTIC_PLANT_ID ELSE PLANT_ID END AS NAME' || CHR(10) || 'FROM   SCM_MST_SITE S' || CHR(10) || 'INNER JOIN (SELECT DISTINCT I.DIVISION_ID, I.COMPANY_ID, I.SCP_OPERATION_GROUP --[C20200608-000328] SalesCompany 콤보는 Item Master의 Company ID, Operation Group 기준으로 조회' || CHR(10) || '			FROM   SCM_MST_PROJECT_ITEM SI' || CHR(10) || '			INNER JOIN SCM_MST_ITEM_SN I' || CHR(10) || '			ON     SI.ITEM_ID = I.ITEM_ID' || CHR(10) || '			--AND    SCP_OPERATION_GROUP IS NOT NULL --[C20200608-000328]' || CHR(10) || '			WHERE  1=1 --si.valid_yn = ''Y'' --[C20200818-000264] Project_Item Master Valid 조건 제외, Item Master Valid 조건 추가' || CHR(10) || '			AND    I.ACTIVE_FLAG = ''Y''' || CHR(10) || '			AND    (I.DIVISION_ID LIKE ''81%'' OR I.DIVISION_ID = ''82'')' || CHR(10) || '			AND    I.ITEM_TYPE IS NOT NULL --[C20200626-000172] SalesCompany, SalesPlant 에 Item Type is not null 조건 추가' || CHR(10) || '			AND    (@divisionId IS NULL OR @divisionId='''' OR SI.DIVISION_ID=@divisionId)' || CHR(10) || '			AND    (@projectCode IS NULL OR @projectCode='''' OR SI.PROJECT_CODE=@projectCode)' || CHR(10) || '			AND    (@itemId IS NULL OR @itemId='''' OR SI.ITEM_ID=@itemId)' || CHR(10) || '			UNION ALL' || CHR(10) || '			SELECT DISTINCT I.DIVISION_ID, I.COMPANY_ID, I.SCP_OPERATION_GROUP --[C20200608-000328]' || CHR(10) || '			FROM   SCM_MST_ITEM_SN I' || CHR(10) || '			WHERE  1=1' || CHR(10) || '			AND    I.ACTIVE_FLAG = ''Y'' --[C20200818-000264]' || CHR(10) || '			AND    I.DIVISION_ID IN (''40'')' || CHR(10) || '			AND    I.ITEM_TYPE IS NOT NULL --[C20200626-000172]' || CHR(10) || '			AND    (@divisionId IS NULL OR @divisionId='''' OR I.DIVISION_ID=@divisionId)' || CHR(10) || '			AND    (@itemId IS NULL OR @itemId='''' OR I.ITEM_ID=@itemId)' || CHR(10) || '			) SS' || CHR(10) || 'ON  S.DIVISION_ID = SS.DIVISION_ID' || CHR(10) || 'AND S.OPERATION_GROUP = NVL(SS.SCP_OPERATION_GROUP, S.OPERATION_GROUP)' || CHR(10) || 'AND S.COMPANY_ID = SS.COMPANY_ID --[C20200608-000328] SalesPlant 콤보는 Item Master의 Company ID, Operation Group 기준으로 조회' || CHR(10) || 'WHERE  1 = 1' || CHR(10) || 'AND    SITE_TYPE = ''PLANT''' || CHR(10) || '--AND    OSP_YN    <> ''Y''' || CHR(10) || 'AND    (@companyId IS NULL OR @companyId='''' OR S.COMPANY_ID=@companyId)' || CHR(10) || 'AND    (@divisionId IS NULL OR @divisionId='''' OR S.DIVISION_ID=@divisionId)' || CHR(10) || 'AND    @itemId IS NOT NULL  -- 원문 ELSE(ISNULL(@Param4,'''')<>'''') Oracle 등가 — ''''=NULL 방언이라 <>'''' 직역은 항상 UNKNOWN' || CHR(10) || 'UNION ALL' || CHR(10) || 'SELECT DISTINCT' || CHR(10) || '	   S.DIVISION_ID AS DIVISION_ID' || CHR(10) || '	 , PLANT_ID AS CODE' || CHR(10) || '	 , PLANT_ID AS NAME' || CHR(10) || 'FROM   SCM_MST_SITE S' || CHR(10) || 'WHERE  1 = 1' || CHR(10) || 'AND    SITE_TYPE = ''CORP''' || CHR(10) || 'AND    (@companyId IS NULL OR @companyId='''' OR S.COMPANY_ID=@companyId)' || CHR(10) || 'AND    (@divisionId IS NULL OR @divisionId='''' OR S.DIVISION_ID=@divisionId)' || CHR(10) || 'AND    @itemId IS NOT NULL  -- 원문 ELSE(ISNULL(@Param4,'''')<>'''') Oracle 등가 — ''''=NULL 방언이라 <>'''' 직역은 항상 UNKNOWN' || CHR(10) || '       )' || CHR(10) || ' ORDER BY UPPER(CODE)' || CHR(10) || '        , UPPER(NAME)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'ScmSitebyEndCustomer40' SQL_ID, 'DM' MDU_DIVS_CD, 'Scm Site 40' SQL_NM, 'SELECT A.SCM_SITE_ID      AS CODE' || CHR(13) || CHR(10) || '     , A.SITE_DESCRIPTION AS NAME' || CHR(13) || CHR(10) || '  FROM SCM_MST_SITE A' || CHR(13) || CHR(10) || ' WHERE 1 = 1' || CHR(13) || CHR(10) || '   AND A.DIVISION_ID IN ( SELECT IA.UNIT_ID' || CHR(13) || CHR(10) || '                            FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M IA' || CHR(13) || CHR(10) || '                           WHERE IA.USER_GR_ID IN ( SELECT SA.USER_GR_ID' || CHR(13) || CHR(10) || '                                                      FROM SCM_ADM_USER_GR_MPG_M SA' || CHR(13) || CHR(10) || '                                                     WHERE SA.USE_YN = ''Y''' || CHR(13) || CHR(10) || '                                                       AND SA.USER_ID = @sesUserId )' || CHR(13) || CHR(10) || '                             AND IA.UNIT_TP_CD = ''D''' || CHR(13) || CHR(10) || '                             AND IA.USE_YN = ''Y''' || CHR(13) || CHR(10) || '                             AND IA.USER_ID = @sesUserId )' || CHR(13) || CHR(10) || '   AND A.DIVISION_ID = ''40''' || CHR(13) || CHR(10) || '   AND A.SITE_TYPE = ''SALES''' || CHR(13) || CHR(10) || '   AND ( @endCustomer IS NULL' || CHR(13) || CHR(10) || '         OR @endCustomer = ''ALL''' || CHR(13) || CHR(10) || '         OR EXISTS ( SELECT 1' || CHR(13) || CHR(10) || '                       FROM SCM_MST_SITE_ITEM XA' || CHR(13) || CHR(10) || '                      WHERE XA.DIVISION_ID = A.DIVISION_ID' || CHR(13) || CHR(10) || '                        AND XA.SCM_SITE_ID = A.SCM_SITE_ID' || CHR(13) || CHR(10) || '                        AND INSTR('','' || @endCustomer || '','', '','' || XA.PROJECT_CODE || '','') > 0 ) )' || CHR(13) || CHR(10) || ' ORDER BY UPPER(A.SCM_SITE_ID)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'SiteByEndCustomer' SQL_ID, 'DM' MDU_DIVS_CD, 'SCM Site by End Customer' SQL_NM, 'SELECT X.CODE' || CHR(13) || CHR(10) || '     , X.NAME' || CHR(13) || CHR(10) || 'FROM (' || CHR(13) || CHR(10) || '  SELECT DISTINCT A.SCM_SITE_ID AS CODE' || CHR(13) || CHR(10) || '       , A.SCM_SITE_ID AS NAME' || CHR(13) || CHR(10) || '  FROM SCM_MST_SITE A' || CHR(13) || CHR(10) || '  WHERE 1 = 1' || CHR(13) || CHR(10) || '    AND NVL(@divisionId, ''~'') <> ''40''' || CHR(13) || CHR(10) || '    AND A.SITE_TYPE = ''SALES''' || CHR(13) || CHR(10) || '    AND ( @endCustomer IS NULL' || CHR(13) || CHR(10) || '      OR @endCustomer = ''ALL''' || CHR(13) || CHR(10) || '      OR INSTR('','' || @endCustomer || '','', '','' || A.END_CUSTOMER || '','') > 0 )' || CHR(13) || CHR(10) || '    AND ( @divisionId IS NULL' || CHR(13) || CHR(10) || '      OR @divisionId = ''ALL''' || CHR(13) || CHR(10) || '      OR INSTR('','' || @divisionId || '','', '','' || A.DIVISION_ID || '','') > 0 )' || CHR(13) || CHR(10) || '    AND A.DIVISION_ID IN (' || CHR(13) || CHR(10) || '    SELECT U.UNIT_ID' || CHR(13) || CHR(10) || '    FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M U' || CHR(13) || CHR(10) || '    WHERE U.UNIT_TP_CD = ''D''' || CHR(13) || CHR(10) || '      AND U.USE_YN = ''Y''' || CHR(13) || CHR(10) || '      AND U.USER_ID = @sesUserId' || CHR(13) || CHR(10) || '      AND U.USER_GR_ID IN (' || CHR(13) || CHR(10) || '      SELECT G.USER_GR_ID' || CHR(13) || CHR(10) || '      FROM SCM_ADM_USER_GR_MPG_M G' || CHR(13) || CHR(10) || '      WHERE G.USER_ID = @sesUserId' || CHR(13) || CHR(10) || '        AND G.USE_YN = ''Y'' ) )' || CHR(13) || CHR(10) || '    AND ( NVL(@validYn, ''N'') <> ''Y''' || CHR(13) || CHR(10) || '      OR A.VALID_YN = ''Y'' )' || CHR(13) || CHR(10) || '  UNION ALL' || CHR(13) || CHR(10) || '  SELECT DISTINCT A.SCM_SITE_ID AS CODE' || CHR(13) || CHR(10) || '       , A.SCM_SITE_ID AS NAME' || CHR(13) || CHR(10) || '  FROM SCM_MST_SITE A' || CHR(13) || CHR(10) || '  LEFT JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID' || CHR(13) || CHR(10) || '    AND A.SCM_SITE_ID = B.SCM_SITE_ID' || CHR(13) || CHR(10) || '  WHERE 1 = 1' || CHR(13) || CHR(10) || '    AND NVL(@divisionId, ''~'') = ''40''' || CHR(13) || CHR(10) || '    AND A.SITE_TYPE = ''SALES''' || CHR(13) || CHR(10) || '    AND B.PROJECT_CODE IS NOT NULL' || CHR(13) || CHR(10) || '    AND ( @endCustomer IS NULL' || CHR(13) || CHR(10) || '      OR @endCustomer = ''ALL''' || CHR(13) || CHR(10) || '      OR INSTR('','' || @endCustomer || '','', '','' || B.PROJECT_CODE || '','') > 0 )' || CHR(13) || CHR(10) || '    AND ( @divisionId IS NULL' || CHR(13) || CHR(10) || '      OR @divisionId = ''ALL''' || CHR(13) || CHR(10) || '      OR INSTR('','' || @divisionId || '','', '','' || A.DIVISION_ID || '','') > 0 )' || CHR(13) || CHR(10) || '    AND A.DIVISION_ID IN (' || CHR(13) || CHR(10) || '    SELECT U.UNIT_ID' || CHR(13) || CHR(10) || '    FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M U' || CHR(13) || CHR(10) || '    WHERE U.UNIT_TP_CD = ''D''' || CHR(13) || CHR(10) || '      AND U.USE_YN = ''Y''' || CHR(13) || CHR(10) || '      AND U.USER_ID = @sesUserId' || CHR(13) || CHR(10) || '      AND U.USER_GR_ID IN (' || CHR(13) || CHR(10) || '      SELECT G.USER_GR_ID' || CHR(13) || CHR(10) || '      FROM SCM_ADM_USER_GR_MPG_M G' || CHR(13) || CHR(10) || '      WHERE G.USER_ID = @sesUserId' || CHR(13) || CHR(10) || '        AND G.USE_YN = ''Y'' ) )' || CHR(13) || CHR(10) || '    AND ( NVL(@validYn, ''N'') <> ''Y''' || CHR(13) || CHR(10) || '      OR A.VALID_YN = ''Y'' ) ) X' || CHR(13) || CHR(10) || 'ORDER BY UPPER(X.CODE)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'SoldCustomer' SQL_ID, 'DM' MDU_DIVS_CD, '사업부 → 팀 → Sold Customer' SQL_NM, 'SELECT X1.*, SOLD_CUSTOMER_CODE AS CODE, SOLD_CUSTOMER_NAME AS NAME FROM ( SELECT X0.*, DIVISION_ID AS DIVISION_CODE, DEPT_ID AS TEAM_CODE, DEPT_NAME AS TEAM_NAME, SOLD_CUSTOMER AS SOLD_CUSTOMER_CODE FROM ( SELECT V.DIVISION_ID, V.DIVISION_ID || '' '' || V.DIVISION_NAME AS DIVISION_NAME, T.DEPT_ID, (SELECT CASE @sesLangCd WHEN ''EN'' THEN D9.DEPT_NAME_EN WHEN ''CN'' THEN D9.DEPT_NAME_CN ELSE D9.DEPT_NAME_KO END FROM SCM_MST_SSO_DEPT_INFO D9 WHERE D9.DEPT_ID = T.DEPT_ID) AS DEPT_NAME, S.SEGMENT2 AS SOLD_CUSTOMER, NVL(S.SEGMENT3, S.SEGMENT2) AS SOLD_CUSTOMER_NAME FROM SCM_MST_DIVISION V JOIN ( SELECT DISTINCT A.DIVISION_ID, B.DEPT_ID FROM SCM_MST_SITE A JOIN SCM_MST_SSO_DEPT_INFO B ON (SELECT MAX(SI9.DEPT_ID) FROM SCM_MST_SITE_ITEM SI9 WHERE SI9.DIVISION_ID = A.DIVISION_ID AND SI9.SCM_SITE_ID = A.SCM_SITE_ID) = B.DEPT_ID WHERE A.SITE_TYPE = ''SALES'' UNION SELECT DISTINCT A.DIVISION_ID, C.DEPT_ID FROM SCM_MST_SITE_ITEM A JOIN SCM_MST_SSO_DEPT_INFO C ON A.DEPT_ID = C.DEPT_ID WHERE A.DIVISION_ID = ''40'' ) T ON V.DIVISION_ID = T.DIVISION_ID JOIN SCM_ADM_LOOKUP_MASTER_DETAIL S ON S.SEGMENT1 = V.DIVISION_ID AND S.LOOKUP_TYPE = ''SOLD_CUSTOMER'' AND S.VALID_YN = ''Y'' WHERE V.ATTRIBUTE3 <> ''EE'' AND V.VALID_YN = ''Y'' AND ( @divisionId IS NULL OR S.SEGMENT1 = @divisionId ) AND V.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'') ORDER BY UPPER(V.DIVISION_ID), UPPER(T.DEPT_ID), S.DISPLAY_SEQ, UPPER(S.SEGMENT2) ) X0 ) X1' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'TeambyDivision' SQL_ID, 'DM' MDU_DIVS_CD, 'TeambyDivision' SQL_NM, 'SELECT X.CODE' || CHR(13) || CHR(10) || '     , X.NAME' || CHR(13) || CHR(10) || 'FROM (' || CHR(13) || CHR(10) || '  SELECT DISTINCT A.DEPT_ID AS CODE' || CHR(13) || CHR(10) || '       , CASE NVL((' || CHR(13) || CHR(10) || '      SELECT MAX(U.LANG_CD)' || CHR(13) || CHR(10) || '      FROM SCM_ADM_USER_M U' || CHR(13) || CHR(10) || '      WHERE U.USER_ID = @sesUserId ), ''KO'') WHEN ''EN'' THEN B.DEPT_NAME_EN WHEN ''CN'' THEN B.DEPT_NAME_CN ELSE B.DEPT_NAME_KO END AS NAME' || CHR(13) || CHR(10) || '  FROM SCM_MST_SITE_ITEM A' || CHR(13) || CHR(10) || '       , SCM_MST_SSO_DEPT_INFO B' || CHR(13) || CHR(10) || '  WHERE A.DEPT_ID = B.DEPT_ID' || CHR(13) || CHR(10) || '    AND ( NVL(@validYn, ''N'') <> ''Y''' || CHR(13) || CHR(10) || '      OR A.VALID_YN = ''Y'' )' || CHR(13) || CHR(10) || '    AND NVL(@divisionId, ''ALL'') <> ''40''' || CHR(13) || CHR(10) || '    AND ( NVL(@divisionId, ''ALL'') = ''ALL''' || CHR(13) || CHR(10) || '      OR INSTR('','' || @divisionId || '','', '','' || A.DIVISION_ID || '','') > 0 )' || CHR(13) || CHR(10) || '    AND A.DIVISION_ID IN (' || CHR(13) || CHR(10) || '    SELECT U.UNIT_ID' || CHR(13) || CHR(10) || '    FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M U' || CHR(13) || CHR(10) || '    WHERE U.UNIT_TP_CD = ''D''' || CHR(13) || CHR(10) || '      AND U.USE_YN = ''Y''' || CHR(13) || CHR(10) || '      AND U.USER_GR_ID IN (' || CHR(13) || CHR(10) || '      SELECT G.USER_GR_ID' || CHR(13) || CHR(10) || '      FROM SCM_ADM_USER_GR_MPG_M G' || CHR(13) || CHR(10) || '      WHERE G.USER_ID = @sesUserId' || CHR(13) || CHR(10) || '        AND G.USE_YN = ''Y'' )' || CHR(13) || CHR(10) || '      AND U.USER_ID = @sesUserId )' || CHR(13) || CHR(10) || '  UNION ALL' || CHR(13) || CHR(10) || '  SELECT DISTINCT A.DEPT_ID AS CODE' || CHR(13) || CHR(10) || '       , CASE NVL((' || CHR(13) || CHR(10) || '      SELECT MAX(U.LANG_CD)' || CHR(13) || CHR(10) || '      FROM SCM_ADM_USER_M U' || CHR(13) || CHR(10) || '      WHERE U.USER_ID = @sesUserId ), ''KO'') WHEN ''EN'' THEN C.DEPT_NAME_EN WHEN ''CN'' THEN C.DEPT_NAME_CN ELSE C.DEPT_NAME_KO END AS NAME' || CHR(13) || CHR(10) || '  FROM SCM_MST_SITE_ITEM A' || CHR(13) || CHR(10) || '       , SCM_MST_SSO_DEPT_INFO C' || CHR(13) || CHR(10) || '  WHERE A.DEPT_ID = C.DEPT_ID' || CHR(13) || CHR(10) || '    AND ( NVL(@validYn, ''N'') <> ''Y''' || CHR(13) || CHR(10) || '      OR A.VALID_YN = ''Y'' )' || CHR(13) || CHR(10) || '    AND A.DIVISION_ID = ''40''' || CHR(13) || CHR(10) || '    AND NVL(@divisionId, ''ALL'') = ''40'' ) X' || CHR(13) || CHR(10) || 'ORDER BY UPPER(X.NAME)' || CHR(13) || CHR(10) || '     , UPPER(X.CODE)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'TeambyDivision2' SQL_ID, 'DM' MDU_DIVS_CD, 'TeambyDivision2 (전체 부서, 변수없이 DISTINCT)' SQL_NM, 'SELECT CODE, NAME FROM ( SELECT DISTINCT A.DEPT_ID AS CODE , CASE @langCd WHEN ''EN'' THEN C.DEPT_NAME_EN WHEN ''CN'' THEN C.DEPT_NAME_CN ELSE C.DEPT_NAME_KO END AS NAME FROM SCM_MST_SITE_ITEM A , SCM_MST_SSO_DEPT_INFO C WHERE A.DEPT_ID = C.DEPT_ID AND A.DIVISION_ID IN (''40'', ''42'', ''44'') AND NVL(@divisionId,''ALL'') = ''ALL'' UNION SELECT DISTINCT A.DEPT_ID AS CODE , CASE @langCd WHEN ''EN'' THEN B.DEPT_NAME_EN WHEN ''CN'' THEN B.DEPT_NAME_CN ELSE B.DEPT_NAME_KO END AS NAME FROM SCM_MST_SITE_ITEM A , SCM_MST_SSO_DEPT_INFO B WHERE A.DEPT_ID = B.DEPT_ID AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'') AND NVL(@divisionId,''ALL'') = ''ALL'' UNION SELECT DISTINCT A.DEPT_ID AS CODE , CASE @langCd WHEN ''EN'' THEN C.DEPT_NAME_EN WHEN ''CN'' THEN C.DEPT_NAME_CN ELSE C.DEPT_NAME_KO END AS NAME FROM SCM_MST_SITE_ITEM A , SCM_MST_SSO_DEPT_INFO C WHERE A.DEPT_ID = C.DEPT_ID AND A.DIVISION_ID = ''40'' AND NVL(@divisionId,''ALL'') = ''40'' UNION SELECT DISTINCT A.DEPT_ID AS CODE , CASE @langCd WHEN ''EN'' THEN B.DEPT_NAME_EN WHEN ''CN'' THEN B.DEPT_NAME_CN ELSE B.DEPT_NAME_KO END AS NAME FROM SCM_MST_SITE_ITEM A , SCM_MST_SSO_DEPT_INFO B WHERE A.DEPT_ID = B.DEPT_ID AND (NVL(@divisionId,''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || A.DIVISION_ID || '','') > 0) AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'') AND NVL(@divisionId,''ALL'') NOT IN (''ALL'',''40'') ) ORDER BY UPPER(NAME), UPPER(CODE)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'YesOrNo' SQL_ID, 'ALL' MDU_DIVS_CD, 'YesOrNo' SQL_NM, 'SELECT ''Y'' AS CODE, ''Y'' AS NAME FROM DUAL UNION ALL SELECT ''N'' AS CODE, ''N'' AS NAME FROM DUAL' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));

COMMIT;
